/*
 * SysCacheGetAttr
 *
 *		Given a tuple previously fetched by SearchSysCache(),
 *		extract a specific attribute.
 *
 * This is equivalent to using heap_getattr() on a tuple fetched
 * from a non-cached relation.  Usually, this is only used for attributes
 * that could be NULL or variable length; the fixed-size attributes in
 * a system table are accessed just by mapping the tuple onto the C struct
 * declarations from include/catalog/.
 *
 * As with heap_getattr(), if the attribute is of a pass-by-reference type
 * then a pointer into the tuple data area is returned --- the caller must
 * not modify or pfree the datum!
 *
 * Note: it is legal to use SysCacheGetAttr() with a cacheId referencing
 * a different cache for the same catalog the tuple was fetched from.
 */
pub unsafe fn SysCacheGetAttr(
    cacheId: c_int,
    tup: HeapTuple,
    attributeNumber: AttrNumber,
    isNull: *mut bool,
) -> Datum {
    /*
     * We just need to get the TupleDesc out of the cache entry, and then we
     * can apply heap_getattr().  Normally the cache control data is already
     * valid (because the caller recently fetched the tuple via this same
     * cache), but there are cases where we have to initialize the cache here.
     */
    if cacheId < 0 || cacheId >= SysCacheSize || !PointerIsValid(SysCache[cacheId as usize]) {
        elog!(ERROR, "invalid cache ID: {}", cacheId);
    }
    if !PointerIsValid((*SysCache[cacheId as usize]).cc_tupdesc) {
        InitCatCachePhase2(SysCache[cacheId as usize], false);
        Assert!(PointerIsValid((*SysCache[cacheId as usize]).cc_tupdesc));
    }

    heap_getattr(
        tup,
        attributeNumber,
        (*SysCache[cacheId as usize]).cc_tupdesc,
        isNull,
    )
}

/*
 * SysCacheGetAttrNotNull
 *
 * As above, a version of SysCacheGetAttr which knows that the attr cannot
 * be NULL.
 */
pub unsafe fn SysCacheGetAttrNotNull(
    cacheId: c_int,
    tup: HeapTuple,
    attributeNumber: AttrNumber,
) -> Datum {
    let mut isnull: bool = false;
    let attr: Datum;

    attr = SysCacheGetAttr(cacheId, tup, attributeNumber, &mut isnull);

    if isnull {
        elog!(
            ERROR,
            "unexpected null value in cached tuple for catalog {} column {}",
            CStr_to_display(get_rel_name(cacheinfo[cacheId as usize].reloid)),
            CStr_to_display(NameStr(
                &mut (*TupleDescAttr(
                    (*SysCache[cacheId as usize]).cc_tupdesc,
                    (attributeNumber - 1) as c_int,
                ))
                .attname
            ))
        );
    }

    attr
}

/*
 * GetSysCacheHashValue
 *
 * Get the hash value that would be used for a tuple in the specified cache
 * with the given search keys.
 *
 * The reason for exposing this as part of the API is that the hash value is
 * exposed in cache invalidation operations, so there are places outside the
 * catcache code that need to be able to compute the hash values.
 */
pub unsafe fn GetSysCacheHashValue(
    cacheId: c_int,
    key1: Datum,
    key2: Datum,
    key3: Datum,
    key4: Datum,
) -> uint32 {
    if cacheId < 0 || cacheId >= SysCacheSize || !PointerIsValid(SysCache[cacheId as usize]) {
        elog!(ERROR, "invalid cache ID: {}", cacheId);
    }

    GetCatCacheHashValue(SysCache[cacheId as usize], key1, key2, key3, key4)
}

/*
 * List-search interface
 */
pub unsafe fn SearchSysCacheList(
    cacheId: c_int,
    nkeys: c_int,
    key1: Datum,
    key2: Datum,
    key3: Datum,
) -> *mut catclist {
    if cacheId < 0 || cacheId >= SysCacheSize || !PointerIsValid(SysCache[cacheId as usize]) {
        elog!(ERROR, "invalid cache ID: {}", cacheId);
    }

    SearchCatCacheList(SysCache[cacheId as usize], nkeys, key1, key2, key3)
}

/*
 * SysCacheInvalidate
 *
 *	Invalidate entries in the specified cache, given a hash value.
 *	See CatCacheInvalidate() for more info.
 *
 *	This routine is only quasi-public: it should only be used by inval.c.
 */
pub unsafe fn SysCacheInvalidate(cacheId: c_int, hashValue: uint32) {
    if cacheId < 0 || cacheId >= SysCacheSize {
        elog!(ERROR, "invalid cache ID: {}", cacheId);
    }

    /* if this cache isn't initialized yet, no need to do anything */
    if !PointerIsValid(SysCache[cacheId as usize]) {
        return;
    }

    CatCacheInvalidate(SysCache[cacheId as usize], hashValue);
}

/*
 * Certain relations that do not have system caches send snapshot invalidation
 * messages in lieu of catcache messages.  This is for the benefit of
 * GetCatalogSnapshot(), which can then reuse its existing MVCC snapshot
 * for scanning one of those catalogs, rather than taking a new one, if no
 * invalidation has been received.
 *
 * Relations that have syscaches need not (and must not) be listed here.  The
 * catcache invalidation messages will also flush the snapshot.  If you add a
 * syscache for one of these relations, remove it from this list.
 */
pub unsafe fn RelationInvalidatesSnapshotsOnly(relid: Oid) -> bool {
    match relid {
        DbRoleSettingRelationId
        | DependRelationId
        | SharedDependRelationId
        | DescriptionRelationId
        | SharedDescriptionRelationId
        | SecLabelRelationId
        | SharedSecLabelRelationId => return true,
        _ => {}
    }

    false
}

/*
 * Test whether a relation has a system cache.
 */
pub unsafe fn RelationHasSysCache(relid: Oid) -> bool {
    let mut low: c_int = 0;
    let mut high: c_int = SysCacheRelationOidSize - 1;

    while low <= high {
        let middle: c_int = low + (high - low) / 2;

        if SysCacheRelationOid[middle as usize] == relid {
            return true;
        }
        if SysCacheRelationOid[middle as usize] < relid {
            low = middle + 1;
        } else {
            high = middle - 1;
        }
    }

    false
}

/*
 * Test whether a relation supports a system cache, ie it is either a
 * cached table or the index used for a cache.
 */
pub unsafe fn RelationSupportsSysCache(relid: Oid) -> bool {
    let mut low: c_int = 0;
    let mut high: c_int = SysCacheSupportingRelOidSize - 1;

    while low <= high {
        let middle: c_int = low + (high - low) / 2;

        if SysCacheSupportingRelOid[middle as usize] == relid {
            return true;
        }
        if SysCacheSupportingRelOid[middle as usize] < relid {
            low = middle + 1;
        } else {
            high = middle - 1;
        }
    }

    false
}

/*
 * OID comparator for qsort
 */
unsafe extern "C" fn oid_compare(a: *const c_void, b: *const c_void) -> c_int {
    let oa: Oid = *(a as *const Oid);
    let ob: Oid = *(b as *const Oid);

    pg_cmp_u32(oa, ob)
}

/*
 * Rust-ABI shim over oid_compare for qunique(), whose comparator type is a
 * plain `unsafe fn` (not `extern "C"`).  The libc qsort() above takes the
 * `extern "C"` form directly.
 */
unsafe fn oid_compare_rs(a: *const c_void, b: *const c_void) -> c_int {
    oid_compare(a, b)
}

