/*
 * Helper to render a NUL-terminated C string in an elog! format argument.
 * (In C the %s conversion does this directly; here we wrap the raw pointer.)
 */
unsafe fn CStr_to_display(s: *const c_char) -> &'static str {
    if s.is_null() {
        return "(null)";
    }
    core::ffi::CStr::from_ptr(s).to_str().unwrap_or("(invalid)")
}
